import{describe,it,expect,beforeEach}from"vitest";import{CHAUKHAMBA_DATA,renderChaukhambaFacts,renderChaukhambaTrek,renderChaukhambaGallery,renderChaukhambaAttractions}from"../../frontend/chaukhamba-i/script.js";describe("Chaukhamba I Mountain Explorer Page",()=>{it("contains accurate mountain metadata for Chaukhamba I",()=>{expect(CHAUKHAMBA_DATA.name).toBe("Chaukhamba I"),expect(CHAUKHAMBA_DATA.title).toBe("Mount Chaukhamba I"),expect(CHAUKHAMBA_DATA.elevation).toBe("7,138 m"),expect(CHAUKHAMBA_DATA.elevationFt).toBe("23,419 ft"),expect(CHAUKHAMBA_DATA.state).toBe("Uttarakhand"),expect(CHAUKHAMBA_DATA.range).toContain("Garhwal"),expect(CHAUKHAMBA_DATA.firstAscent).toBe("June 13, 1952")}),it("defines four summits of the massif and glacier systems",()=>{expect(Array.isArray(CHAUKHAMBA_DATA.massifPeaks)).toBe(!0),expect(CHAUKHAMBA_DATA.massifPeaks.length).toBe(4);const e=CHAUKHAMBA_DATA.massifPeaks.map(e=>e.name);expect(e).toContain("Chaukhamba I"),expect(e).toContain("Chaukhamba II"),expect(e).toContain("Chaukhamba III"),expect(e).toContain("Chaukhamba IV"),expect(Array.isArray(CHAUKHAMBA_DATA.glaciers)).toBe(!0),expect(CHAUKHAMBA_DATA.glaciers).toContain("Gangotri Glacier"),expect(CHAUKHAMBA_DATA.glaciers).toContain("Satopanth Glacier")}),it("contains fast facts grid data",()=>{expect(Array.isArray(CHAUKHAMBA_DATA.facts)).toBe(!0),expect(CHAUKHAMBA_DATA.facts.length).toBeGreaterThanOrEqual(6),CHAUKHAMBA_DATA.facts.forEach(e=>{expect(e).toHaveProperty("title"),expect(e).toHaveProperty("value"),expect(e).toHaveProperty("description"),expect(e).toHaveProperty("icon")})}),it("contains Satopanth Tal & Base Camp trekking guide steps",()=>{expect(Array.isArray(CHAUKHAMBA_DATA.trekkingInfo)).toBe(!0),expect(CHAUKHAMBA_DATA.trekkingInfo.length).toBe(4);const e=CHAUKHAMBA_DATA.trekkingInfo.find(e=>e.stage.includes("Satopanth Tal"));expect(e).toBeDefined(),expect(e.altitude).toBe("4,600 m")}),it("contains gallery items and nearby attractions",()=>{expect(Array.isArray(CHAUKHAMBA_DATA.gallery)).toBe(!0),expect(CHAUKHAMBA_DATA.gallery.length).toBeGreaterThanOrEqual(3),expect(Array.isArray(CHAUKHAMBA_DATA.nearbyAttractions)).toBe(!0),expect(CHAUKHAMBA_DATA.nearbyAttractions.length).toBeGreaterThanOrEqual(5);const e=CHAUKHAMBA_DATA.nearbyAttractions.map(e=>e.name);expect(e).toContain("Satopanth Tal"),expect(e).toContain("Mana Village"),expect(e).toContain("Badrinath Temple"),expect(e).toContain("Gaumukh & Gangotri Glacier")}),describe("DOM Rendering Helpers",()=>{let e;beforeEach(()=>{e=document.createElement("div")}),it("renders facts cards into HTML container",()=>{renderChaukhambaFacts(CHAUKHAMBA_DATA.facts,e),expect(e.children.length).toBe(CHAUKHAMBA_DATA.facts.length),expect(e.innerHTML).toContain("7,138 m")}),it("renders trekking step cards into HTML container",()=>{renderChaukhambaTrek(CHAUKHAMBA_DATA.trekkingInfo,e),expect(e.children.length).toBe(CHAUKHAMBA_DATA.trekkingInfo.length),expect(e.innerHTML).toContain("Satopanth Tal")}),it("renders gallery cards into HTML container",()=>{renderChaukhambaGallery(CHAUKHAMBA_DATA.gallery,e),expect(e.children.length).toBe(CHAUKHAMBA_DATA.gallery.length)}),it("renders attractions cards into HTML container",()=>{renderChaukhambaAttractions(CHAUKHAMBA_DATA.nearbyAttractions,e),expect(e.children.length).toBe(CHAUKHAMBA_DATA.nearbyAttractions.length),expect(e.innerHTML).toContain("Satopanth Tal")})})});